// Fission products, chapter 3 "TRISO kernel: how fission products leave a
// bare UO2 sphere" (lessons 10-28): the widgets. Each registers with
// Lesson.widget(id, make) and runs on the page that has its element.
// Data: kernel-data.js (generated by crates/dhoby-ghaut/examples/
// lesson_triso_kernel), kernel-recorded.js (cited / pending),
// cascade-recorded.js (the RustBCA ranges, for recoil). Models:
// kernel-physics.js; the Potts coarsening and the sphere walks run in
// kernel-worker.js. The chemical FAMILY chosen on lesson 11 is remembered
// (per browser) and carried by every later demo.
(function () {
  "use strict";
  var L = window.Lesson, css = L.css, el = L.el;
  var KD = function () { return window.KERNEL_DATA; };
  var KR = function () { return window.KERNEL_RECORDED; };
  var KP = function () { return window.KernelPhysics; };
  var FAMCOL = { gas: "#2f7fd8", volatile: "#7a4cc2", alkearth: "#2a9d55", noblemetal: "#b85c38", lanth: "#d4a017", silver: "#7f8c8d" };

  // ─── The family thread ─────────────────────────────────────────────────
  var famKey = "fp-kernel-family";
  function famId() {
    try { var v = localStorage.getItem(famKey); if (v && KR().families.some(function (f) { return f.id === v; })) return v; } catch (e) {}
    return "gas";
  }
  function setFam(v) { try { localStorage.setItem(famKey, v); } catch (e) {} }
  function fam() { var id = famId(); return KR().families.filter(function (f) { return f.id === id; })[0]; }
  function famPicker(body, redraw) {
    L.buttons(body, "Family (carried from lesson 11)", KR().families.map(function (f) { return [f.id, f.name]; }), famId(), function (v) { setFam(v); redraw(); });
  }
  function zOf(sym) { var e = KD().elements.filter(function (x) { return x.sym === sym; })[0]; return e ? e.z : null; }
  function classOf(z) { return KD().elements[z - 1].dClass; }
  function dKernel(z, tC) { var c = KD().dClasses[classOf(z)]; return KP().dAt(tC, KD().tC, c.kernel); }
  function fmtLen(m) { return m >= 1e-3 ? (m * 1e3).toPrecision(3) + " mm" : (m * 1e6).toPrecision(3) + " µm"; }
  function wrap(ctx, text, x, y, maxW, lh) {
    var words = text.split(" "), line = "";
    words.forEach(function (wd) {
      var t = line ? line + " " + wd : wd;
      if (ctx.measureText(t).width > maxW && line) { ctx.fillText(line, x, y); y += lh; line = wd; } else line = t;
    });
    if (line) { ctx.fillText(line, x, y); y += lh; }
    return y;
  }
  var worker = null, wid = 0, handlers = {};
  function ask(msg, cb) {
    if (!worker) { worker = new Worker("kernel-worker.js"); worker.onmessage = function (e) { var h = handlers[e.data.id]; if (h) h(e.data); }; }
    msg.id = ++wid; handlers[msg.id] = cb; worker.postMessage(msg); return msg.id;
  }

  // ─── 10: the polycrystal (ILLUSTRATIVE) ───────────────────────────────
  function poly(root) {
    var r = KP().rng(11), W = 2000, seeds = [];
    for (var i = 0; i < 36; i++) seeds.push({ x: r() * W, y: r() * W, th: r() * Math.PI / 2, hue: (i * 47) % 360 });
    // Centre the view on a boundary: midway between seed 0 and its nearest.
    var s0 = seeds[0], best = null, bd = Infinity;
    seeds.forEach(function (s, k) { if (k) { var d = Math.hypot(s.x - s0.x, s.y - s0.y); if (d < bd) { bd = d; best = s; } } });
    var C = { x: (s0.x + best.x) / 2, y: (s0.y + best.y) / 2 };
    function nearest(x, y) { var b = 0, bd2 = Infinity; for (var k = 0; k < seeds.length; k++) { var dx = seeds[k].x - x, dy = seeds[k].y - y, d = dx * dx + dy * dy; if (d < bd2) { bd2 = d; b = k; } } return b; }
    function hash(a, b) { var h = Math.imul(a | 0, 374761393) ^ Math.imul(b | 0, 668265263); h = Math.imul(h ^ (h >>> 13), 1274126177); return ((h ^ (h >>> 16)) >>> 0) / 4294967296; }
    var frame = new L.Frame(root, {
      reset: function () {}, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var top = 58, vh = h - top, sc = Math.pow(zoom, 1.9) * Math.max(w, vh) / W;
        var X = function (x) { return w / 2 + (x - C.x) * sc; }, Y = function (y) { return top + vh / 2 + (y - C.y) * sc; };
        if (sc < 3) {
          var img = ctx.createImageData(Math.ceil(w), Math.ceil(vh)), step = 2;
          for (var py = 0; py < vh; py += step) for (var px = 0; px < w; px += step) {
            var k = nearest(C.x + (px - w / 2) / sc, C.y + (py - vh / 2) / sc), hue = seeds[k].hue;
            var rr = 150 + 60 * Math.cos(hue * Math.PI / 180), gg = 150 + 60 * Math.cos((hue - 120) * Math.PI / 180), bb = 150 + 60 * Math.cos((hue + 120) * Math.PI / 180);
            for (var dy = 0; dy < step; dy++) for (var dx = 0; dx < step; dx++) {
              var o = 4 * ((py + dy) * img.width + px + dx); if (o >= img.data.length) continue;
              img.data[o] = rr; img.data[o + 1] = gg; img.data[o + 2] = bb; img.data[o + 3] = 255;
            }
          }
          ctx.putImageData(img, 0, top);
          ctx.fillStyle = css("--fg", "#1d2125"); ctx.font = "12px system-ui, sans-serif";
          wrap(ctx, "Grains (ILLUSTRATIVE): each colour is one crystal orientation. Zoom in on the boundary at the centre.", 10, top + 16, w - 20, 15);
          return "A polycrystal: grains of one crystal each, meeting at grain boundaries. Zoom in (+) to see atoms.";
        }
        // Atoms: each grain's lattice, rotated, kept where that grain is nearest.
        var x0 = C.x - w / 2 / sc, x1 = C.x + w / 2 / sc, y0 = C.y - vh / 2 / sc, y1 = C.y + vh / 2 / sc;
        var near = [];
        seeds.forEach(function (s, k) { if (Math.hypot(s.x - C.x, s.y - C.y) < bd * 3) near.push(k); });
        near.forEach(function (k) {
          var s = seeds[k], c = Math.cos(s.th), sn = Math.sin(s.th), R = Math.hypot(x1 - x0, y1 - y0);
          var ux = (C.x - s.x) * c + (C.y - s.y) * sn, uy = -(C.x - s.x) * sn + (C.y - s.y) * c;
          for (var i = Math.floor(ux - R); i <= ux + R; i++) for (var j = Math.floor(uy - R); j <= uy + R; j++) {
            var x = s.x + i * c - j * sn, y = s.y + i * sn + j * c;
            if (x < x0 - 1 || x > x1 + 1 || y < y0 - 1 || y > y1 + 1) continue;
            if (nearest(x, y) !== k) continue;
            var hsh = hash(i * 7 + k, j);
            if (hsh < 0.01) { ctx.strokeStyle = "#555"; ctx.beginPath(); ctx.arc(X(x), Y(y), sc * 0.3, 0, 2 * Math.PI); ctx.stroke(); continue; }
            ctx.fillStyle = hsh > 0.992 ? "#c0392b" : "hsl(" + s.hue + ",45%,55%)";
            ctx.beginPath(); ctx.arc(X(x), Y(y), Math.max(1, sc * 0.32), 0, 2 * Math.PI); ctx.fill();
          }
        });
        ctx.fillStyle = css("--fg", "#1d2125"); ctx.font = "12px system-ui, sans-serif";
        wrap(ctx, "ILLUSTRATIVE atoms. Rows meet at the boundary out of step. Empty circle: a vacancy. Red: a foreign atom.", 10, top + 16, w - 20, 15);
        return "Zoomed to atoms at a grain boundary: on each side the atoms sit in neat rows, but the rows point different ways, and the boundary between is disordered.";
      },
      panel: function (body) { body.append(el("p", { "class": "w-note" }, "A cartoon, not a micrograph: grain shapes are a random Voronoi pattern, and the defect fractions are chosen to be visible. Zoom in all the way to reach atoms.")); }
    });
    return frame;
  }

  // ─── 11: families ─────────────────────────────────────────────────────
  function family(root) {
    var frame = new L.Frame(root, {
      reset: function () {}, tick: function () { return false; },
      draw: function (ctx, w, h) {
        var fs = KR().families, cols = w < 520 ? 2 : 3, bw = (w - 20) / cols, bh = Math.min(96, (h - 70) / Math.ceil(fs.length / cols) - 8), sel = famId();
        ctx.font = "13px system-ui, sans-serif";
        fs.forEach(function (f, i) {
          var x = 10 + (i % cols) * bw, y = 64 + Math.floor(i / cols) * (bh + 8);
          ctx.fillStyle = FAMCOL[f.id]; ctx.globalAlpha = f.id === sel ? 0.9 : 0.25; ctx.fillRect(x, y, bw - 8, bh); ctx.globalAlpha = 1;
          ctx.fillStyle = f.id === sel ? "#fff" : css("--fg", "#1d2125");
          ctx.font = "bold 13px system-ui, sans-serif"; ctx.fillText(f.name, x + 8, y + 18);
          ctx.font = "13px system-ui, sans-serif"; ctx.fillText(f.members.join(", "), x + 8, y + 38);
          ctx.font = "11px system-ui, sans-serif"; wrap(ctx, f.state ? f.state + " (source pending)" : "", x + 8, y + 56, bw - 24, 13);
        });
        var f = fam();
        return "Chosen: " + f.name + " (" + f.members.join(", ") + "). Later lessons follow this family. What chemical form each takes in UO2: source pending (Kleykamp 1985 is the candidate, not yet read).";
      },
      panel: function (body, redraw) { famPicker(body, redraw); }
    });
    return frame;
  }

  // ─── 12: grain growth (ILLUSTRATIVE Potts) ────────────────────────────
  function potts(root) {
    var st = { kT: 0.6, g: null, L: 96, q: 48, sweep: 0, bf: [], running: false, id: 0 };
    function run() {
      st.bf = []; st.running = true;
      if (st.id) worker.postMessage({ cmd: "stop" });
      st.id = ask({ cmd: "potts", L: st.L, q: st.q, kT: st.kT, sweeps: 300, every: 5, seed: 3 }, function (m) {
        if (m.id !== st.id) return;
        if (m.cmd === "frame") { st.g = m.g; st.sweep = m.sweep; st.bf.push([m.sweep, m.bf]); frame.redraw(); }
        else st.running = false;
      });
    }
    var frame = new L.Frame(root, {
      reset: function () { run(); }, tick: function () { return false; },
      onSeen: function () { if (!st.g && !st.running) run(); },
      draw: function (ctx, w, h, zoom) {
        if (!st.g) return "Starting the coarsening in a Web Worker…";
        var side = Math.min(w, h - 120) * zoom, px = side / st.L, x0 = (w - side) / 2, y0 = 60;
        for (var i = 0; i < st.g.length; i++) {
          var o = st.g[i];
          ctx.fillStyle = "hsl(" + ((o * 360 / st.q) | 0) + ",40%,60%)";
          ctx.fillRect(x0 + (i % st.L) * px, y0 + ((i / st.L) | 0) * px, Math.ceil(px), Math.ceil(px));
        }
        // 1 / boundary fraction against sweeps: grows as grains grow.
        var gy = h - 50, gx0 = 40, gx1 = w - 20;
        ctx.strokeStyle = css("--muted", "#5b636b"); ctx.beginPath(); ctx.moveTo(gx0, gy); ctx.lineTo(gx1, gy); ctx.stroke();
        var mx = 0; st.bf.forEach(function (p) { mx = Math.max(mx, 1 / p[1]); });
        ctx.strokeStyle = "#b85c38"; ctx.beginPath();
        st.bf.forEach(function (p, k) { var x = gx0 + p[0] / 300 * (gx1 - gx0), y = gy - 40 * (1 / p[1]) / mx; if (k) ctx.lineTo(x, y); else ctx.moveTo(x, y); });
        ctx.stroke();
        ctx.fillStyle = css("--muted", "#5b636b"); ctx.font = "11px system-ui, sans-serif"; ctx.fillText("grain size (1 / boundary length) against time", gx0, gy + 14);
        return "ILLUSTRATIVE coarsening (a Potts model): sweep " + st.sweep + " of 300. Boundaries cost energy, so small grains are swallowed and the rest grow. Temperature knob kT' = " + st.kT.toFixed(2) + " (model units).";
      },
      panel: function (body) {
        L.slider(body, "Temperature (model units, illustrative)", 0, 1.5, 0.05, st.kT, function (v) { st.kT = v; return v.toFixed(2); });
        var b = el("button", { type: "button", "class": "w-opt" }, "Restart with this temperature");
        b.onclick = run; body.append(b, el("p", { "class": "w-note" }, "Runs in a Web Worker and streams a picture every five sweeps. A Potts model is a teaching model of coarsening, not UO2 kinetics (SCIANTIX's grain-growth options are cited on the page)."));
      }
    });
    return frame;
  }

  // ─── 13: pores climbing the gradient (ILLUSTRATIVE) ───────────────────
  function pores(root) {
    var st = { t: 0, n: 60, p: [], trails: [], dT: 1, play: true };
    function init() { var r = KP().rng(4); st.p = []; st.trails = []; for (var i = 0; i < st.n; i++) { var rad = 0.35 + 0.6 * Math.sqrt(r()), a = 2 * Math.PI * r(); st.p.push({ r: rad, a: a, r0: rad }); } st.t = 0; }
    init();
    var frame = new L.Frame(root, {
      reset: init,
      tick: function (dt) {
        if (!st.play) return false;
        st.t += dt;
        // Speed rises steeply with the local temperature (an Arrhenius-like
        // factor in model units) and with the gradient; both illustrative.
        st.p.forEach(function (q) { if (q.r > 0.03) { var T = 1 - q.r * q.r; q.r = Math.max(0.02, q.r - dt * 0.25 * st.dT * q.r * Math.exp(-3 * (1 - T) / (0.3 + 0.7 * st.dT))); } });
        return st.t < 30;
      },
      draw: function (ctx, w, h, zoom) {
        var R = zoom * Math.min(w, h - 70) / 2.3, cx = w / 2, cy = 60 + (h - 60) / 2;
        var g = ctx.createRadialGradient(cx, cy, 0, cx, cy, R);
        g.addColorStop(0, "rgba(220,60,30,0.85)"); g.addColorStop(1, "rgba(240,200,120,0.6)");
        ctx.fillStyle = g; ctx.beginPath(); ctx.arc(cx, cy, R, 0, 2 * Math.PI); ctx.fill();
        st.p.forEach(function (q) {
          ctx.strokeStyle = "rgba(60,40,30,0.35)"; ctx.lineWidth = 2;
          ctx.beginPath(); ctx.moveTo(cx + q.r0 * R * Math.cos(q.a), cy + q.r0 * R * Math.sin(q.a)); ctx.lineTo(cx + q.r * R * Math.cos(q.a), cy + q.r * R * Math.sin(q.a)); ctx.stroke();
          ctx.fillStyle = "#fff"; ctx.beginPath(); ctx.arc(cx + q.r * R * Math.cos(q.a), cy + q.r * R * Math.sin(q.a), 3, 0, 2 * Math.PI); ctx.fill();
        });
        var arrived = st.p.filter(function (q) { return q.r <= 0.03; }).length;
        ctx.fillStyle = "#fff"; ctx.beginPath(); ctx.arc(cx, cy, R * 0.03 * Math.sqrt(1 + arrived), 0, 2 * Math.PI); ctx.fill();
        ctx.fillStyle = css("--fg", "#1d2125"); ctx.font = "12px system-ui, sans-serif";
        wrap(ctx, "ILLUSTRATIVE pellet cross-section: hot centre (red), cooler rim. White: pores; grey trails: the columnar grains they leave.", 10, 74, w - 20, 15);
        return "Pores move up the temperature gradient, towards the hot centre, and gather there as a central hole. " + arrived + " of " + st.n + " have arrived. Mechanism and rates: source pending.";
      },
      panel: function (body, redraw, play) {
        L.slider(body, "Temperature difference centre to rim (illustrative)", 0.2, 1.5, 0.1, st.dT, function (v) { st.dT = v; return v.toFixed(1) + " (model units)"; });
        var b = el("button", { type: "button", "class": "w-opt" }, "Start again");
        b.onclick = function () { init(); st.play = true; play(); };
        body.append(b);
      }
    });
    return frame;
  }

  // ─── 14: in the grain / out of it (a table) ───────────────────────────
  function inOut(node) {
    var rows = [
      ["gas", "Diffuse to the boundary, with trapping in and knock-back out of intragranular bubbles (SCIANTIX gas_diffusion.rst)", "Collect in boundary bubbles; released when bubbles interconnect and vent (SCIANTIX intergranular_bubble_behavior.rst, grain_boundary_venting.rst). Not at once."],
      ["volatile", "source pending", "Compounds, and vapour along porosity: source pending"],
      ["alkearth", "source pending", "Oxides, retained in the carbon layers: source pending"],
      ["noblemetal", "Metallic precipitates: source pending", "Pd moves to the coatings and attacks SiC: source pending"],
      ["lanth", "Stay dissolved: source pending", "source pending"],
      ["silver", "source pending", "source pending"]
    ];
    var body = node.querySelector("tbody"), F = {}; KR().families.forEach(function (f) { F[f.id] = f; });
    rows.forEach(function (r) {
      var tr = el("tr");
      if (r[0] === famId()) tr.style.fontWeight = "600";
      tr.append(el("td", { "data-label": "Family" }, F[r[0]].name), el("td", { "data-label": "In the grain" }, r[1]), el("td", { "data-label": "At the boundary and beyond" }, r[2]));
      body.append(tr);
    });
  }

  // ─── 15: the periodic table the code sees ─────────────────────────────
  var PT = [
    "H................He", "LiBe..........BCNOFNe", "NaMg..........AlSiPSClAr",
    "KCaScTiVCrMnFeCoNiCuZnGaGeAsSeBrKr", "RbSrYZrNbMoTcRuRhPdAgCdInSnSbTeIXe",
    "CsBa*HfTaWReOsIrPtAuHgTlPbBiPoAtRn", "FrRa*", "", "**LaCePrNdPmSmEuGdTbDyHoErTmYbLu", "**AcThPaUNpPuAmCmBkCfEsFm"
  ];
  function ptLayout() {
    // Split each row string into symbols; '.' is an empty cell, '*' marks
    // the f-block gap (row) or indent (f rows).
    var cells = [];
    PT.forEach(function (row, ri) {
      var col = 0, i = 0;
      if (ri === 0) { cells.push(["H", 0, 0]); cells.push(["He", 0, 17]); return; }
      while (i < row.length) {
        var c = row[i];
        if (c === ".") { col++; i++; continue; }
        if (c === "*") { col++; i++; if (ri >= 8) continue; continue; }
        var sym = c, n = row[i + 1];
        if (n && n >= "a" && n <= "z") { sym += n; i += 2; } else i++;
        // Rows 1-2: jump the gap for B..Ne and Al..Ar.
        if ((ri === 1 || ri === 2) && cells.filter(function (x) { return x[1] === ri; }).length === 2) col = 12;
        cells.push([sym, ri, col]); col++;
      }
    });
    return cells;
  }
  function ptable(root) {
    var cells = ptLayout(), st = { colour: "class", pick: "Cs", tC: 1200, hits: [] };
    var CLS = ["#c8ced3", "#2f7fd8", "#7a4cc2", "#2a9d55", "#7f8c8d"];
    var NG = {}; KR().nureg1465.groups.forEach(function (g, i) { g[1].forEach(function (s) { NG[s] = i; }); });
    var frame = new L.Frame(root, {
      reset: function () {}, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var cw = Math.min((w - 12) / 18, 40) * zoom, ch = cw * 1.05, x0 = 6, y0 = 62;
        st.hits = [];
        ctx.font = Math.max(8, cw * 0.38) + "px system-ui, sans-serif";
        cells.forEach(function (c) {
          var z = zOf(c[0]); if (!z) return;
          var e = KD().elements[z - 1], x = x0 + c[2] * cw, y = y0 + c[1] * ch;
          var col = "#eee";
          if (st.colour === "class") col = CLS[e.dClass % CLS.length];
          else if (st.colour === "group") col = { NobleGas: "#2f7fd8", Halogen: "#7a4cc2", SpecialMetal: "#2a9d55", Silver: "#7f8c8d", Other: "#c8ced3" }[e.group];
          else if (st.colour === "nureg") col = NG[c[0]] === undefined ? "#f4f4f4" : "hsl(" + NG[c[0]] * 45 + ",50%,62%)";
          else if (st.colour === "family") { var f = KR().families.filter(function (f) { return f.members.indexOf(c[0]) >= 0; })[0]; col = f ? FAMCOL[f.id] : "#f4f4f4"; }
          ctx.fillStyle = col; ctx.fillRect(x, y, cw - 2, ch - 2);
          if (c[0] === st.pick) { ctx.strokeStyle = "#000"; ctx.lineWidth = 2; ctx.strokeRect(x, y, cw - 2, ch - 2); }
          ctx.fillStyle = "#111"; ctx.fillText(c[0], x + 2, y + ch * 0.6);
          if (st.colour !== "nureg" && !e.plates) { ctx.fillText("~", x + cw * 0.62, y + ch * 0.35); }
          st.hits.push([x, y, cw, ch, c[0]]);
        });
        // The picked element's D(T) beside its class (kernel).
        var z = zOf(st.pick), e = KD().elements[z - 1], cls = KD().dClasses[e.dClass];
        var gy0 = y0 + 10 * ch + 22, gy1 = h - 30, gx0 = 50, gx1 = w - 14;
        if (gy1 - gy0 > 60) {
          var lo = Infinity, hi = -Infinity; KD().dClasses.forEach(function (c) { c.kernel.forEach(function (v) { lo = Math.min(lo, Math.log10(v)); hi = Math.max(hi, Math.log10(v)); }); });
          var PX = function (t) { return gx0 + (t - KD().tC[0]) / (KD().tC[KD().tC.length - 1] - KD().tC[0]) * (gx1 - gx0); };
          var PY = function (v) { return gy1 - (Math.log10(v) - lo) / (hi - lo) * (gy1 - gy0); };
          ctx.strokeStyle = css("--muted", "#5b636b"); ctx.lineWidth = 1; ctx.strokeRect(gx0, gy0, gx1 - gx0, gy1 - gy0);
          KD().dClasses.forEach(function (c, k) {
            ctx.strokeStyle = CLS[k % CLS.length]; ctx.lineWidth = k === e.dClass ? 3 : 1; ctx.beginPath();
            c.kernel.forEach(function (v, i) { var x = PX(KD().tC[i]), y = PY(v); if (i) ctx.lineTo(x, y); else ctx.moveTo(x, y); }); ctx.stroke();
          });
          ctx.fillStyle = css("--fg", "#1d2125"); ctx.font = "11px system-ui, sans-serif";
          ctx.fillText("kernel D (log) against T, 400-2000 °C; thick: " + st.pick + "'s class", gx0, gy0 - 4);
        }
        var mates = cls.members.map(function (zz) { return KD().elements[zz - 1].sym; });
        return st.pick + ": TRISO-ATOPS group " + e.group + "; shares its diffusion coefficient with " + (mates.length > 12 ? mates.length - 1 + " other elements (the nominal value)" : mates.filter(function (s) { return s !== st.pick; }).join(", ") || "no other element") + "; " + (e.plates ? "plates out" : "does not plate out (~)") + ". Tap an element.";
      },
      panel: function (body, redraw) {
        L.buttons(body, "Colour by", [["class", "Shared D (code)"], ["group", "TRISO-ATOPS group"], ["nureg", "NUREG-1465 group"], ["family", "Our families"]], st.colour, function (v) { st.colour = v; redraw(); });
        body.append(el("p", { "class": "w-note" }, "'~' marks elements that do not plate out in TRISO-ATOPS's routing (the noble gases). NUREG-1465's groups are LWR release groups (Table 3.8), shown for comparison."));
      }
    });
    frame.canvas.addEventListener("pointerdown", function (ev) {
      var b = frame.canvas.getBoundingClientRect(), x = ev.clientX - b.left, y = ev.clientY - b.top;
      st.hits.forEach(function (hh) { if (x >= hh[0] && x <= hh[0] + hh[2] && y >= hh[1] && y <= hh[1] + hh[3]) { st.pick = hh[4]; frame.redraw(); } });
    });
    return frame;
  }

  // ─── 16: Booth on one grain ───────────────────────────────────────────
  function boothW(root) {
    var st = { tC: 1300, aUm: 5, logt: 5, mc: [], paths: null, busy: false };
    function x() { var f = fam(); return dKernel(f.rep, st.tC) * Math.pow(10, st.logt) / Math.pow(st.aUm * 1e-6, 2); }
    function run() {
      st.busy = true; var xx = x();
      ask({ cmd: "walk", n: 600, x: xx, steps: 400, seed: 17, keep: 12 }, function (m) { st.mc.push([xx, m.f]); st.paths = m.paths; st.busy = false; frame.redraw(); });
    }
    var frame = new L.Frame(root, {
      reset: function () { st.mc = []; st.paths = null; }, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var K = KP(), xx = x(), f = K.boothF(xx), fg = css("--fg", "#1d2125");
        // Left: the sphere and some walks; right/bottom: Booth's curve.
        var half = w > 560, R = Math.min(half ? w / 4 : w / 3.2, (h - 70) / (half ? 2.4 : 4.6)) * zoom, cx = half ? w / 4 : w / 2, cy = 60 + R + 10;
        ctx.strokeStyle = fg; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.arc(cx, cy, R, 0, 2 * Math.PI); ctx.stroke();
        (st.paths || []).forEach(function (p) {
          ctx.strokeStyle = "rgba(47,127,216,0.6)"; ctx.lineWidth = 1; ctx.beginPath();
          p.forEach(function (q, i) { if (i) ctx.lineTo(cx + q[0] * R, cy + q[1] * R); else ctx.moveTo(cx + q[0] * R, cy + q[1] * R); }); ctx.stroke();
        });
        var gx0 = half ? w / 2 + 20 : 40, gx1 = w - 14, gy0 = half ? 70 : cy + R + 30, gy1 = h - 30;
        var lx0 = -6, lx1 = 1, PX = function (v) { return gx0 + (Math.log10(v) - lx0) / (lx1 - lx0) * (gx1 - gx0); }, PY = function (v) { return gy1 - v * (gy1 - gy0); };
        ctx.strokeStyle = css("--muted", "#5b636b"); ctx.strokeRect(gx0, gy0, gx1 - gx0, gy1 - gy0);
        ctx.strokeStyle = "#b85c38"; ctx.lineWidth = 2; ctx.beginPath();
        KD().booth.x.forEach(function (v, i) { var X = PX(v), Y = PY(KD().booth.f[i]); if (i) ctx.lineTo(X, Y); else ctx.moveTo(X, Y); }); ctx.stroke();
        ctx.fillStyle = "#2f7fd8"; st.mc.forEach(function (p) { if (p[0] > 1e-6 && p[0] < 10) { ctx.beginPath(); ctx.arc(PX(p[0]), PY(p[1]), 5, 0, 2 * Math.PI); ctx.fill(); } });
        if (xx > 1e-6 && xx < 10) { ctx.strokeStyle = fg; ctx.beginPath(); ctx.moveTo(PX(xx), gy0); ctx.lineTo(PX(xx), gy1); ctx.stroke(); }
        ctx.fillStyle = css("--muted", "#5b636b"); ctx.font = "11px system-ui, sans-serif";
        ctx.fillText("released fraction against D t / a² (log); line: boon-lay's Booth", gx0, gy0 - 4);
        return fam().name + " (D of " + KD().elements[fam().rep - 1].sym + ") at " + st.tC + " °C, grain radius " + st.aUm + " µm (illustrative), after " + fmtT(Math.pow(10, st.logt)) + ": D t / a² = " + xx.toExponential(2) + ", Booth releases " + (100 * f).toPrecision(3) + " %." + (st.busy ? " Walking…" : st.mc.length ? " Last walk: " + (100 * st.mc[st.mc.length - 1][1]).toPrecision(3) + " % of 600 atoms." : "");
      },
      panel: function (body, redraw) {
        famPicker(body, redraw);
        L.slider(body, "Temperature (°C)", 600, 2000, 20, st.tC, function (v) { st.tC = v; redraw(); return v + " °C"; });
        L.slider(body, "Grain radius (µm, illustrative)", 1, 30, 1, st.aUm, function (v) { st.aUm = v; redraw(); return v + " µm"; });
        L.slider(body, "Time (log10 s)", 0, 9, 0.25, st.logt, function (v) { st.logt = v; redraw(); return fmtT(Math.pow(10, v)); });
        var b = el("button", { type: "button", "class": "w-opt" }, "Walk 600 atoms (worker)");
        b.onclick = function () { run(); redraw(); };
        body.append(b);
      }
    });
    return frame;
  }
  function fmtT(s) {
    var u = [[3.15576e7, "y"], [86400, "d"], [3600, "h"], [60, "min"], [1, "s"]];
    for (var i = 0; i < u.length; i++) if (s >= u[i][0]) return (s / u[i][0]).toPrecision(3) + " " + u[i][1];
    return s.toPrecision(3) + " s";
  }

  // ─── 17: many Booth spheres ───────────────────────────────────────────
  function many(root) {
    var st = { many: true, radial: true, wide: false, aUm: 5, prof: 0, tShift: 0 };
    function curves() {
      var K = KP(), f = fam(), P = KD().profiles[st.prof], n = 60;
      var radii = st.many ? K.lognormalRadii(st.aUm * 1e-6, st.wide ? 0.6 : 0.2, n) : [st.aUm * 1e-6];
      // Temperatures: each grain at a radius in the kernel, uniform by volume,
      // from the profile (radial) or all at the surface value (uniform).
      var ts = radii.map(function (a, i) {
        var rho = Math.cbrt((i + 0.5) / radii.length), Tk = P.tSurf + st.tShift;
        if (st.radial) { var j = Math.min(P.r.length - 1, Math.round(rho * (P.r.length - 1))); Tk = P.t[j] + st.tShift; }
        return Tk - 273.15;
      });
      var out = [], eq = [];
      for (var lt = 0; lt <= 9; lt += 0.15) {
        var t = Math.pow(10, lt);
        out.push([lt, K.manySpheres(radii, ts, t, function (tc) { return dKernel(f.rep, tc); })]);
        eq.push([lt, K.boothF(dKernel(f.rep, P.tSurf + st.tShift - 273.15) * t / Math.pow(st.aUm * 1e-6, 2))]);
      }
      return { m: out, e: eq, ts: ts };
    }
    var frame = new L.Frame(root, {
      reset: function () {}, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var c = curves(), x0 = 46, x1 = w - 14, y0 = 70, y1 = h - 36;
        var PX = function (lt) { return x0 + lt / 9 * (x1 - x0); }, PY = function (v) { return y1 - v * (y1 - y0) * zoom; };
        ctx.strokeStyle = css("--muted", "#5b636b"); ctx.strokeRect(x0, y0, x1 - x0, y1 - y0);
        [[c.e, "#888", "one equivalent sphere, surface temperature"], [c.m, "#b85c38", "the model as set in the panel"]].forEach(function (k, i) {
          ctx.strokeStyle = k[1]; ctx.lineWidth = 2; ctx.beginPath(); k[0].forEach(function (p, j) { if (j) ctx.lineTo(PX(p[0]), PY(p[1])); else ctx.moveTo(PX(p[0]), PY(p[1])); }); ctx.stroke();
          ctx.fillStyle = k[1]; ctx.font = "11px system-ui, sans-serif"; ctx.fillText(k[2], x0 + 6, y0 + 14 + 14 * i);
        });
        ctx.fillStyle = css("--muted", "#5b636b");
        [0, 3, 6, 9].forEach(function (lt) { ctx.fillText(fmtT(Math.pow(10, lt)), PX(lt) - 10, y1 + 14); });
        var spread = Math.max.apply(null, c.ts) - Math.min.apply(null, c.ts);
        return fam().name + ": released fraction against time (log). Kernel temperatures span " + spread.toFixed(2) + " K across the grains at HTR-10's average power (from the generated profile), so the radial profile barely matters there; the size spread matters more. Grain sizes are illustrative.";
      },
      panel: function (body, redraw) {
        famPicker(body, redraw);
        L.toggle(body, "Many spheres (off: one)", st.many, function (v) { st.many = v; redraw(); });
        L.toggle(body, "Radial temperature (off: uniform)", st.radial, function (v) { st.radial = v; redraw(); });
        L.toggle(body, "Wide size spread (off: narrow)", st.wide, function (v) { st.wide = v; redraw(); });
        L.slider(body, "Median grain radius (µm, illustrative)", 1, 30, 1, st.aUm, function (v) { st.aUm = v; redraw(); return v + " µm"; });
        L.buttons(body, "Kernel surface temperature", KD().profiles.map(function (p, i) { return [i, p.tSurf + " K"]; }), st.prof, function (v) { st.prof = +v; redraw(); });
        L.slider(body, "Shift every temperature by (K)", 0, 600, 20, st.tShift, function (v) { st.tShift = v; redraw(); return "+" + v + " K"; });
      }
    });
    return frame;
  }

  // ─── 18: two scales ───────────────────────────────────────────────────
  function twoScales(root) {
    var st = { aUm: 5, tC: 1300 };
    var frame = new L.Frame(root, {
      reset: function () {}, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var K = KP(), r = KD().kernelRadius, a = st.aUm * 1e-6, ab = Math.sqrt(2 * a * r), D = dKernel(fam().rep, st.tC);
        var x0 = 46, x1 = w - 14, y0 = 70, y1 = h - 36, PX = function (lt) { return x0 + lt / 10 * (x1 - x0); }, PY = function (v) { return y1 - v * (y1 - y0) * zoom; };
        ctx.strokeStyle = css("--muted", "#5b636b"); ctx.strokeRect(x0, y0, x1 - x0, y1 - y0);
        [[a, "#2f7fd8", "open paths: the grain boundary is the exit (a = grain)"], [r, "#b85c38", "closed paths: the whole kernel is one sphere (a = kernel)"], [ab, "#2a9d55", "TRISO-ATOPS's blend: a = √(2 · grain · kernel)"]].forEach(function (k, i) {
          ctx.strokeStyle = k[1]; ctx.lineWidth = 2; ctx.beginPath();
          for (var lt = 0; lt <= 10; lt += 0.1) { var v = K.boothF(D * Math.pow(10, lt) / (k[0] * k[0])); if (lt) ctx.lineTo(PX(lt), PY(v)); else ctx.moveTo(PX(lt), PY(v)); }
          ctx.stroke(); ctx.fillStyle = k[1]; ctx.font = "11px system-ui, sans-serif"; ctx.fillText(k[2], x0 + 6, y0 + 14 + 14 * i);
        });
        ctx.fillStyle = css("--muted", "#5b636b"); [0, 3, 6, 9].forEach(function (lt) { ctx.fillText(fmtT(Math.pow(10, lt)), PX(lt) - 10, y1 + 14); });
        return fam().name + " at " + st.tC + " °C. Grain " + fmtLen(a) + " (illustrative), kernel " + fmtLen(r) + " (HTR-10), blend " + fmtLen(ab) + ". The same D, three answers: the radius you choose is the model.";
      },
      panel: function (body, redraw) {
        famPicker(body, redraw);
        L.slider(body, "Grain radius (µm, illustrative)", 1, 30, 1, st.aUm, function (v) { st.aUm = v; redraw(); return v + " µm"; });
        L.slider(body, "Temperature (°C)", 600, 2000, 20, st.tC, function (v) { st.tC = v; redraw(); return v + " °C"; });
      }
    });
    return frame;
  }

  // ─── 19: the R/B fingerprint ──────────────────────────────────────────
  function rbW(root) {
    var st = { aUm: 5, tC: 1300, recoil: true };
    var frame = new L.Frame(root, {
      reset: function () {}, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var K = KP(), a = st.aUm * 1e-6, D = dKernel(54, st.tC), Dp = D / (a * a);
        var x0 = 50, x1 = w - 14, y0 = 70, y1 = h - 40, lmin = -10, lmax = 0, rmin = -6, rmax = 0;
        var PX = function (l) { return x0 + (Math.log10(l) - lmin) / (lmax - lmin) * (x1 - x0); }, PY = function (v) { return y1 - (Math.log10(Math.max(v, 1e-12)) - rmin) / (rmax - rmin) * (y1 - y0); };
        ctx.strokeStyle = css("--muted", "#5b636b"); ctx.strokeRect(x0, y0, x1 - x0, y1 - y0);
        ctx.save(); ctx.beginPath(); ctx.rect(x0, y0, x1 - x0, y1 - y0); ctx.clip();
        ctx.strokeStyle = "#b85c38"; ctx.lineWidth = 2; ctx.beginPath();
        for (var e = lmin; e <= lmax; e += 0.05) { var l = Math.pow(10, e), v = K.boothRB(Math.sqrt(l / Dp)); if (e > lmin) ctx.lineTo(PX(l), PY(v)); else ctx.moveTo(PX(l), PY(v)); }
        ctx.stroke();
        var rec = window.CASCADE_RECORDED ? window.CASCADE_RECORDED.rustbca.heavy.rangeUm * 1e-6 : null, rr = null;
        if (st.recoil && rec) {
          rr = K.recoilEscape(rec / KD().kernelRadius, 40000, 3);
          ctx.strokeStyle = "#7a4cc2"; ctx.setLineDash([6, 4]); ctx.beginPath(); ctx.moveTo(x0, PY(rr)); ctx.lineTo(x1, PY(rr)); ctx.stroke(); ctx.setLineDash([]);
        }
        ctx.restore();
        ctx.fillStyle = "#2f7fd8";
        KD().rbIsotopes.forEach(function (iso) {
          var l = Math.log(2) / iso.t12, v = K.boothRB(Math.sqrt(l / Dp)), X = PX(l);
          if (X < x0 || X > x1) return;
          ctx.beginPath(); ctx.arc(X, PY(v), 4, 0, 2 * Math.PI); ctx.fill();
          ctx.save(); ctx.translate(X + 3, PY(v) - 6); ctx.rotate(-0.6); ctx.font = "10px system-ui, sans-serif"; ctx.fillText(iso.name, 0, 0); ctx.restore();
        });
        ctx.fillStyle = css("--muted", "#5b636b"); ctx.font = "11px system-ui, sans-serif";
        for (var k = lmin; k <= lmax; k += 2) ctx.fillText("1e" + k, PX(Math.pow(10, k)) - 10, y1 + 14);
        ctx.fillText("decay constant λ (1/s), log", x1 - 150, y1 + 28); ctx.fillText("R/B (log)", 6, y0 + 10);
        return "Xe/Kr in grains of " + st.aUm + " µm (illustrative) at " + st.tC + " °C. Diffusion: the curve falls with slope −½ where decay wins. " + (rr !== null ? "Recoil from the kernel surface (dashed, the RustBCA range of the record, illustrative): flat, " + rr.toExponential(1) + ", whatever the half-life." : "");
      },
      panel: function (body, redraw) {
        L.slider(body, "Grain radius (µm, illustrative)", 1, 30, 1, st.aUm, function (v) { st.aUm = v; redraw(); return v + " µm"; });
        L.slider(body, "Temperature (°C)", 600, 2000, 20, st.tC, function (v) { st.tC = v; redraw(); return v + " °C"; });
        L.toggle(body, "Recoil line", st.recoil, function (v) { st.recoil = v; redraw(); });
      }
    });
    return frame;
  }

  // ─── 20-28: one complication at a time, bending the clean curve ───────
  // Each mode draws the clean many-spheres release (lesson 17's model, at the
  // family's D) and one bent version. Every bend is ILLUSTRATIVE: its size is
  // a slider, not data, because each mechanism's numbers are source pending.
  var BENDS = {
    recoil: ["a constant extra release from the surface skin", function (f, t, k) { return Math.min(1, f + k * 0.05); }],
    knockout: ["a small extra release that does not depend on temperature", function (f, t, k) { return Math.min(1, f + k * 0.02); }],
    sweeping: ["growing grains sweep gas to the boundary: a larger share reaches it", function (f, t, k) { return Math.min(1, f + (1 - f) * k * 0.4 * Math.min(1, Math.log10(1 + t) / 9)); }],
    precursor: ["the atom spends part of its life as a different element with a different D", function (f, t, k, x) { return KP().boothF(x * (1 + 4 * k)); }],
    burst: ["a heat-up partway through: D jumps, and so does the release", function (f, t, k, x) { return t < 1e6 ? f : KP().boothF(x + (t - 1e6) / t * x * 50 * k); }],
    oxygen: ["more oxygen in the fuel speeds diffusion of some species", function (f, t, k, x) { return KP().boothF(x * (1 + 9 * k)); }],
    conductivity: ["a hotter kernel as conductivity falls: higher D everywhere", function (f, t, k, x) { return KP().boothF(x * Math.pow(10, 1.5 * k)); }],
    hbs: ["tiny new grains at the rim: shorter paths there", function (f, t, k, x) { return 0.8 * f + 0.2 * KP().boothF(x * (1 + 99 * k)); }],
    swelling: ["the kernel grows into the buffer's pores (release not changed here)", function (f) { return f; }]
  };
  function bend(root) {
    var mode = root.getAttribute("data-bend"), B = BENDS[mode], st = { k: 0.5, aUm: 5, tC: 1300 };
    var frame = new L.Frame(root, {
      reset: function () {}, tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var K = KP(), D = dKernel(fam().rep, st.tC), a = st.aUm * 1e-6;
        var x0 = 46, x1 = w - 14, y0 = 74, y1 = h - 36, PX = function (lt) { return x0 + lt / 9 * (x1 - x0); }, PY = function (v) { return y1 - v * (y1 - y0) * zoom; };
        ctx.strokeStyle = css("--muted", "#5b636b"); ctx.strokeRect(x0, y0, x1 - x0, y1 - y0);
        var clean = [], bent = [];
        for (var lt = 0; lt <= 9; lt += 0.1) { var t = Math.pow(10, lt), x = D * t / (a * a), f = K.boothF(x); clean.push([lt, f]); bent.push([lt, B[1](f, t, st.k, x)]); }
        [[clean, "#888", "the clean picture (lesson 17)"], [bent, "#b85c38", "bent: " + B[0]]].forEach(function (c, i) {
          ctx.strokeStyle = c[1]; ctx.lineWidth = 2; ctx.beginPath(); c[0].forEach(function (p, j) { if (j) ctx.lineTo(PX(p[0]), PY(p[1])); else ctx.moveTo(PX(p[0]), PY(p[1])); }); ctx.stroke();
          ctx.fillStyle = c[1]; ctx.font = "11px system-ui, sans-serif"; wrap(ctx, c[2], x0 + 6, y0 + 14 + 16 * i, x1 - x0 - 12, 13);
        });
        ctx.fillStyle = css("--muted", "#5b636b"); [0, 3, 6, 9].forEach(function (l) { ctx.fillText(fmtT(Math.pow(10, l)), PX(l) - 10, y1 + 14); });
        return "ILLUSTRATIVE: the size of the bend is the slider, not data (source pending). " + fam().name + ", D of " + KD().elements[fam().rep - 1].sym + " at " + st.tC + " °C, grain " + st.aUm + " µm.";
      },
      panel: function (body, redraw) {
        famPicker(body, redraw);
        L.slider(body, "How strong (illustrative)", 0, 1, 0.05, st.k, function (v) { st.k = v; redraw(); return v.toFixed(2); });
        L.slider(body, "Temperature (°C)", 600, 2000, 20, st.tC, function (v) { st.tC = v; redraw(); return v + " °C"; });
      }
    });
    return frame;
  }

  // Numbers in the prose, bound by data-kd="...".
  function fillKd() {
    var D = KD(), cls = D.dClasses, big = cls.reduce(function (m, c) { return c.members.length > m.members.length ? c : m; });
    var named = cls.filter(function (c) { return c !== big; }).map(function (c) { return "{" + c.members.map(function (z) { return D.elements[z - 1].sym; }).join(", ") + "}"; });
    var worst = 0;
    D.mcBooth.forEach(function (p) { var se = Math.sqrt(p.booth * (1 - p.booth) / p.n); worst = Math.max(worst, Math.abs(p.mc - p.booth) / se); });
    var rises = D.profiles.map(function (p) { return (p.t[0] - p.tSurf).toFixed(2) + " K at a " + p.tSurf + " K surface"; });
    var x137 = D.rbIsotopes.filter(function (i) { return i.name === "Xe137"; })[0];
    var map = {
      nClasses: String(cls.length), namedClasses: named.join(", "), nominalCount: String(big.members.length),
      nominalD: big.kernel[0].toExponential(0) + " m²/s",
      nonPlating: D.elements.filter(function (e) { return !e.plates; }).map(function (e) { return e.sym; }).join(", "),
      kernelUm: (D.kernelRadius * 1e6).toFixed(0) + " µm", perParticle: (D.power.perParticle * 1e3).toPrecision(3) + " mW",
      qKernel: D.power.qKernel.toPrecision(3) + " W/m³", rises: rises.join(" and "), mcWorst: worst.toFixed(2),
      mcN: String(D.mcBooth[0].n), xe137: x137 ? fmtT(x137.t12) : "—",
      rangeHeavy: window.CASCADE_RECORDED ? window.CASCADE_RECORDED.rustbca.heavy.rangeUm + " µm" : "—"
    };
    document.querySelectorAll("[data-kd]").forEach(function (n) { var k = n.getAttribute("data-kd"); if (k in map) n.textContent = map[k]; });
    var tb = document.querySelector("#mc-table tbody");
    if (tb) D.mcBooth.forEach(function (p) {
      var tr = el("tr");
      tr.append(el("td", { "data-label": "T" }, p.tC + " °C"), el("td", { "data-label": "D t / a²" }, String(p.x)), el("td", { "data-label": "Time" }, fmtT(p.time)),
        el("td", { "data-label": "Monte Carlo" }, (100 * p.mc).toFixed(2) + " %"), el("td", { "data-label": "Booth" }, (100 * p.booth).toFixed(2) + " %"));
      tb.append(tr);
    });
  }
  L.widget("kd-numbers", fillKd);
  L.widget("poly", poly);
  L.widget("family", family);
  L.widget("potts", potts);
  L.widget("pores", pores);
  L.widget("inout-table", inOut);
  L.widget("ptable", ptable);
  L.widget("booth", boothW);
  L.widget("many", many);
  L.widget("twoscale", twoScales);
  L.widget("rb", rbW);
  // Deferred scripts run after parsing, before the kit starts the widgets.
  document.querySelectorAll(".widget[data-bend]").forEach(function (n, i) { if (!n.id) n.id = "bend-" + i; L.widget(n.id, bend); });
})();
